// ── Basic WebSocket connection ──
const ws = new WebSocket('wss://api.example.com/chat');

ws.onopen = () => {
    console.log('Connected');
    // Send a JSON message
    ws.send(JSON.stringify({
        type: 'auth',
        token: sessionStorage.getItem('token'),
    }));
};

ws.onmessage = (event) => {
    const msg = JSON.parse(event.data);
    switch (msg.type) {
        case 'chat':     renderMessage(msg.data);   break;
        case 'presence': updateOnlineUsers(msg.data); break;
        case 'typing':   showTypingIndicator(msg.data); break;
        case 'error':    console.error(msg.message); break;
    }
};

ws.onerror = (error) => console.error('WebSocket error:', error);

ws.onclose = (event) => {
    console.log(`Closed: code=${event.code} reason=${event.reason}`);
    // 1000 = normal close, 1001 = going away, 1006 = abnormal (reconnect)
    if (event.code !== 1000) reconnect();
};

// Send a chat message
function sendMessage(text) {
    if (ws.readyState !== WebSocket.OPEN) return;
    ws.send(JSON.stringify({ type: 'chat', text, timestamp: Date.now() }));
}

// ── Auto-reconnect with exponential backoff ──
let reconnectDelay = 1000;

function reconnect() {
    console.log(`Reconnecting in ${reconnectDelay / 1000}s...`);
    setTimeout(() => {
        const newWs = new WebSocket('wss://api.example.com/chat');
        // re-attach event handlers...
        reconnectDelay = Math.min(reconnectDelay * 2, 30_000);  // cap at 30s
    }, reconnectDelay);
}

// ── Heartbeat — keep connection alive through proxies ──
const heartbeat = setInterval(() => {
    if (ws.readyState === WebSocket.OPEN) {
        ws.send(JSON.stringify({ type: 'ping' }));
    }
}, 30_000);

// Clean up on close
ws.addEventListener('close', () => clearInterval(heartbeat));
